// Collapses all sheet rows into one item that holds the IDs of emails already logged.
const ids = [];

for (const row of $input.all()) {
  const value = row.json.MessageId;
  if (value !== undefined && value !== null && String(value).trim() !== '') {
    ids.push(String(value).trim());
  }
}

return [{ json: { existingIds: ids } }];

// Keeps only emails that are not in the sheet yet and prepares clean text for the analysis.
const settings = $('Set Analysis Settings').first().json;
const maxChars = Number(settings.maxBodyChars) || 4000;
const seen = new Set($('Collect Logged IDs').first().json.existingIds || []);

function addressText(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (typeof value.text === 'string') return value.text;
  if (Array.isArray(value.value) && value.value[0]) {
    const first = value.value[0];
    return first.name ? `${first.name} <${first.address}>` : first.address || '';
  }
  return '';
}

function htmlToText(html) {
  return String(html)
    .replace(/<(script|style|head|title)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/(p|div|tr|li|table|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&(nbsp|zwnj|zwj|shy|#8203|#8204|#847|#160);/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&rsquo;|&lsquo;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function cleanText(text) {
  return String(text)
    // Remove links, which are mostly long tracking URLs.
    .replace(/[\[(<]?https?:\/\/[^\s\])>]+[\])>]?/g, ' ')
    // Remove invisible characters that brands use to pad the inbox preview.
    .replace(/[­͏​-‏⁠﻿]/g, '')
    .replace(/[ \t ]+/g, ' ')
    .replace(/ ?\n ?/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function emailDate(json) {
  const raw = json.date || (json.internalDate ? Number(json.internalDate) : '');
  const date = raw ? new Date(raw) : new Date();
  return isNaN(date.getTime()) ? new Date().toISOString() : date.toISOString();
}

const output = [];

for (const item of $input.all()) {
  const json = item.json;
  const messageId = String(json.id || '').trim();

  if (!messageId || seen.has(messageId)) continue;
  seen.add(messageId);

  const rawBody =
    (typeof json.text === 'string' && json.text.trim()) ||
    (typeof json.html === 'string' && htmlToText(json.html)) ||
    json.snippet ||
    '';

  const body = cleanText(rawBody).slice(0, maxChars);
  const snippet = cleanText(json.snippet || body).replace(/\n+/g, ' ').slice(0, 200);

  output.push({
    json: {
      messageId,
      date: emailDate(json),
      from: addressText(json.from || json.From),
      subject: json.subject || json.Subject || '',
      snippet,
      body,
    },
  });
}

return output;

// Reads Claude's JSON answer for each email and builds one sheet row per email.
// Emails whose analysis failed are skipped, so they are picked up again on the next run.
const emails = $('Filter and Prepare New Emails').all();
const results = $input.all();

function emailFor(index) {
  if (results.length === emails.length) return emails[index].json;
  try {
    return $('Filter and Prepare New Emails').itemMatching(index).json;
  } catch (error) {
    return null;
  }
}

function getText(json) {
  if (Array.isArray(json.content)) {
    const block = json.content.find((part) => part && typeof part.text === 'string');
    if (block) return block.text;
  }
  if (typeof json.merged_response === 'string') return json.merged_response;
  if (typeof json.text === 'string') return json.text;
  return '';
}

// Takes everything from the first "{" to the last "}".
// This also removes code fences or extra text around the JSON.
function extractJson(text) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return '';
  return text.slice(start, end + 1);
}

const rows = [];

results.forEach((item, index) => {
  if (item.json.error) return;

  const email = emailFor(index);
  if (!email) return;

  let data;
  try {
    data = JSON.parse(extractJson(getText(item.json)));
  } catch (error) {
    return;
  }

  if (!data || !data.summary) return;

  const tactics = Array.isArray(data.key_tactics)
    ? data.key_tactics.join('; ')
    : data.key_tactics || '';

  rows.push({
    json: {
      MessageId: email.messageId,
      Date: email.date,
      From: email.from,
      Subject: email.subject,
      Snippet: email.snippet,
      Competitor: data.competitor || email.from,
      'Email Type': data.email_type || 'other',
      Summary: data.summary,
      'Offer/Hook': data.offer_or_hook || '',
      'Key Tactics': tactics,
      'Brand Response Idea': data.brand_response_idea || '',
    },
  });
});

return rows;
